mapper.select:
SELECT e.course_no AS courseNo, e.student_user_no AS studentUserNo,
/* 출석률 */ COALESCE(( SELECT ROUND( (15 - SUM( CASE WHEN a.attendance_status = 1 THEN 1 WHEN a.attendance_status = 2 THEN 0.5 ELSE 0 END )) / 15 * 100 ,1) FROM tb_attendance a WHERE a.course_no = e.course_no AND a.student_user_no = e.student_user_no ), 100.0) AS attendanceRate,
/* 기존 시험 점수 (tb_grade에서 가져옴) */ COALESCE((SELECT grade_score FROM tb_grade WHERE course_no = e.course_no AND student_user_no = e.student_user_no), NULL) AS examScore,
/* 과제 점수: tb_assignment_submission의 평균 점수를 가져옴 */ COALESCE(( SELECT AVG(tas.assignment_score) FROM tb_assignment_submission tas JOIN tb_assignment ta ON tas.assignment_no = ta.assignment_no WHERE ta.course_no = e.course_no -- 현재 강의의 과제만 AND tas.writer_user_no = e.student_user_no -- 해당 학생이 제출한 과제만 AND tas.assignment_score IS NOT NULL -- 점수가 부여된 과제만 평균 계산 ), 0) AS assignmentScore,
/* 기존 최종 점수 (tb_grade에서 가져옴) */ COALESCE((SELECT grade_final_score FROM tb_grade WHERE course_no = e.course_no AND student_user_no = e.student_user_no), NULL) AS finalScore,
/* 기존 등급 (tb_grade에서 가져옴) */ COALESCE((SELECT grade_value FROM tb_grade WHERE course_no = e.course_no AND student_user_no = e.student_user_no), NULL) AS gradeValue,
100 AS examMaxScore
FROM tb_enrollment e WHERE e.course_no = #{courseNo} AND e.student_user_no = #{studentUserNo}

SELECT COUNT(*)
FROM tb_grade
WHERE student_user_no = #{studentUserNo}
  AND course_no = #{courseNo}

mapper.update:
UPDATE tb_grade
SET grade_score = #{examScore},
    grade_assignment_score = #{assignmentScore},
    grade_value = #{gradeValue},
    grade_final_score = #{finalScore}
WHERE student_user_no = #{studentUserNo}
  AND course_no = #{courseNo}
